"""Replay tests generated by amber for weekly-report v1.

Each source trace is replayed through the program with a cassette backend: every tool call
must match the recording (name + canonical args) in order; llm() steps are served from the
recordings. Run with ``pytest`` from the project root (needs the traces in .amber/traces).
"""

import pytest

from amber.runtime.verify import replay_from_paths

TRACES = ["t1", "t2", "t3"]


@pytest.mark.parametrize("trace_id", TRACES)
def test_replay(trace_id: str) -> None:
    report = replay_from_paths(__file__, trace_id)
    assert report.status == "pass", report.summary()
